INSERT INTO corrections (target_type, target_id, body, created_at) SELECT 'articles', (SELECT id FROM articles WHERE canonical_url = 'https://www.federalreserve.gov/newsevents/pressreleases/enforcement20261008a.htm'), 'The action concerns the holding company; an earlier summary named only the bank.', 1791511200000 WHERE NOT EXISTS (SELECT 1 FROM corrections WHERE target_type = 'articles' AND target_id = (SELECT id FROM articles WHERE canonical_url = 'https://www.federalreserve.gov/newsevents/pressreleases/enforcement20261008a.htm') AND body = 'The action concerns the holding company; an earlier summary named only the bank.');
